337	
338	static int mi_reserve_os_memory_ex2(mi_subproc_t* subproc, size_t size, bool commit, bool allow_large, bool exclusive, mi_arena_id_t* arena_id);
339	
340	// try to reserve a fresh arena space
341	static bool mi_arena_reserve(mi_subproc_t* subproc, size_t req_size, bool allow_large, mi_arena_id_t* arena_id)
342	{
343	  const size_t arena_count = mi_arenas_get_count(subproc);
344	  if (arena_count > (MI_MAX_ARENAS - 4)) return false;
345	
346	  // calc reserve
347	  size_t arena_reserve = mi_option_get_size(mi_option_arena_reserve);
348	  if (arena_reserve == 0) return false;
349	
350	  if (!_mi_os_has_virtual_reserve()) {
351	    arena_reserve = arena_reserve/4;  // be conservative if virtual reserve is not supported (for WASM for example)
352	  }
353	  arena_reserve = _mi_align_up(arena_reserve, MI_ARENA_SLICE_SIZE);
354	
355	  if (arena_count >= 1 && arena_count <= 128) {
356	    // scale up the arena sizes exponentially every 8 entries
357	    const size_t multiplier = (size_t)1 << _mi_clamp(arena_count/8, 0, 16);
358	    size_t reserve = 0;
359	    if (!mi_mul_overflow(multiplier, arena_reserve, &reserve)) {
360	      arena_reserve = reserve;
361	    }
362	  }
363	
364	  // try to accommodate the requested size for huge allocations
365	  req_size = _mi_align_up(req_size + MI_ARENA_MAX_CHUNK_OBJ_SIZE, MI_ARENA_MAX_CHUNK_OBJ_SIZE); // over-reserve for meta-info
366	  if (arena_reserve < req_size) {
367	    arena_reserve = req_size;
368	  }
369	
370	  // check arena bounds
371	  const size_t min_reserve = MI_ARENA_MIN_SIZE;
372	  const size_t max_reserve = MI_ARENA_MAX_SIZE;   // 16 GiB
373	  if (arena_reserve < min_reserve) {
374	    arena_reserve = min_reserve;
375	  }
376	  else if (arena_reserve > max_reserve) {
377	    arena_reserve = max_reserve;
378	  }
379	
380	  // should be able to at least handle the current allocation size
381	  if (arena_reserve < req_size) return false;
382	
383	  // commit eagerly?
384	  bool arena_commit = false;
385	  const bool overcommit = _mi_os_has_overcommit();
386	  if (mi_option_get(mi_option_arena_eager_commit) == 2) { arena_commit = overcommit || mi_option_is_enabled(mi_option_allow_large_os_pages); }
387	  else if (mi_option_get(mi_option_arena_eager_commit) == 1) { arena_commit = true; }
388	
389	  // on an OS with overcommit (Linux) we don't count the commit yet as it is on-demand. Once a slice
390	  // is actually allocated for the first time it will be counted.
391	  const bool adjust = (overcommit && arena_commit);
392	  if (adjust) { mi_subproc_stat_adjust_decrease( subproc, committed, arena_reserve); }
393	  // and try to reserve the arena
394	  int err = mi_reserve_os_memory_ex2(subproc, arena_reserve, arena_commit, allow_large, false /* exclusive? */, arena_id);
395	  if (err != 0) {
396	    if (adjust) { mi_subproc_stat_adjust_increase( subproc, committed, arena_reserve); } // roll back
397	    // failed to allocate: try a smaller size arena as fallback?
398	    const size_t small_arena_reserve = 4 * MI_ARENA_MIN_SIZE; // 128 MiB (or 32 MiB on 32-bit)
399	    if (arena_reserve > small_arena_reserve && small_arena_reserve > req_size) {
400	      // try again
401	      if (adjust) { mi_subproc_stat_adjust_decrease(subproc, committed, small_arena_reserve); }
402	      err = mi_reserve_os_memory_ex2(subproc, small_arena_reserve, arena_commit, allow_large, false /* exclusive? */, arena_id);
403	      if (err != 0 && adjust) { mi_subproc_stat_adjust_increase( subproc, committed, small_arena_reserve); } // roll back
404	    }
405	  }
406	  return (err==0);
407	}
