415	
416	static inline bool mi_arena_is_suitable_ex(mi_arena_t* arena, mi_arena_t* req_arena, bool match_numa, int numa_node, bool allow_pinned) {
417	  if (!allow_pinned && arena->memid.is_pinned) return false;
418	  if (!mi_arena_is_suitable(arena, req_arena)) return false;
419	  if (req_arena == NULL) { // if not specific, check numa affinity
420	    const bool numa_suitable = (numa_node < 0 || arena->numa_node < 0 || arena->numa_node == numa_node);
421	    if (match_numa) { if (!numa_suitable) return false; }
422	               else { if (numa_suitable)  return false; }
423	  }
424	  return true;
425	}
426	
427	// determine the start of search; important to keep heaps and threads
428	// into their own memory regions to reduce contention.
429	static size_t mi_arena_start_idx(mi_heap_t* heap, size_t tseq, size_t arena_cycle) {
430	  const size_t hseq   = heap->heap_seq;
431	  const size_t hcount = mi_atomic_load_relaxed(&heap->subproc->heap_count);
432	  if (arena_cycle <= 1)     return 0;
433	  if (hseq==0 || hcount<=1 || arena_cycle > 0x8FF) return (tseq % arena_cycle); // common for single heap programs
434	
435	  // spread heaps evenly among arena's, and then evenly for threads in their fraction
436	  size_t start;
437	  mi_assert_internal(arena_cycle <= 0x8FF);             // prevent overflow on 32-bit
438	  const size_t frac = (arena_cycle * 256) / hcount;     // fraction in the arena_cycle; at most: arena_cycle * 0x100
439	  if (frac==0) {
440	    // many heaps (> 256 per arena)
441	    start = (hseq % arena_cycle);
442	  }
443	  else {
444	    const size_t hspot = (hseq % hcount);  
445	    start = (frac * hspot) / 256;           // (arena_cycle * (hseq % hcount)) / hcount
446	    if (frac >= 512) {  // at least 2 arena's per heap?
447	      start = start + (tseq % (frac/256));
448	    }
449	  }
450	  mi_assert_internal(start < arena_cycle);
451	  return start;
452	}
453	
454	#define mi_forall_arenas(heap, req_arena, tseq, name_arena) { \
455	  const size_t _arena_count = mi_arenas_get_count(heap->subproc); \
456	  const size_t _arena_cycle = (_arena_count == 0 ? 0 : _arena_count - 1); /* first search the arenas below the last one */ \
457	  /* always start searching in the arena's below the max */ \
458	  const size_t _start = mi_arena_start_idx(heap,tseq,_arena_cycle); \
459	  for (size_t _i = 0; _i < _arena_count; _i++) { \
460	    mi_arena_t* name_arena; \
461	    if (req_arena != NULL) { \
462	      name_arena = req_arena; /* if there is a specific req_arena, only search that one */\
463	      if (_i > 0) break;      /* only once */ \
464	    } \
465	    else { \
466	      size_t _idx; \
467	      if (_i < _arena_cycle) { \
468	        _idx = _i + _start; \
469	        if (_idx >= _arena_cycle) { _idx -= _arena_cycle; } /* adjust so we rotate through the cycle */ \
470	      } \
471	      else { \
472	        _idx = _i; /* remaining arena's after the cycle */ \
473	      } \
474	      name_arena = mi_arena_from_index(heap->subproc,_idx); \
475	    } \
476	    if (name_arena != NULL) \
477	    {
478	
479	#define mi_forall_arenas_end()  \
480	    } \
481	  } \
482	  }
483	
484	#define mi_forall_suitable_arenas(heap, req_arena, tseq, match_numa, numa_node, allow_large, name_arena) \
485	  mi_forall_arenas(heap, req_arena,tseq,name_arena) { \
486	    if (mi_arena_is_suitable_ex(name_arena, req_arena, match_numa, numa_node, allow_large)) { \
487	
488	#define mi_forall_suitable_arenas_end() \
489	  }} \
490	  mi_forall_arenas_end()
