493	  Arena allocation
494	----------------------------------------------------------- */
495	
496	// allocate slices from the arenas
497	static mi_decl_noinline void* mi_arenas_try_find_free(
498	  mi_heap_t* heap, size_t slice_count, size_t alignment,
499	  bool commit, bool allow_large, mi_arena_t* req_arena, size_t tseq, int numa_node, mi_memid_t* memid)
500	{
501	  // mi_assert_internal(slice_count <= mi_slice_count_of_size(MI_ARENA_MAX_CHUNK_OBJ_SIZE));
502	  mi_assert(alignment <= MI_ARENA_SLICE_ALIGN);
503	  if (alignment > MI_ARENA_SLICE_ALIGN) return NULL;
504	
505	  // search arena's
506	  mi_forall_suitable_arenas(heap, req_arena, tseq, true /* only numa matching */, numa_node, allow_large, arena)
507	  {
508	    void* p = mi_arena_try_alloc_at(arena, slice_count, commit, tseq, memid);
509	    if (p != NULL) return p;
510	  }
511	  mi_forall_suitable_arenas_end();
512	  if (numa_node < 0) return NULL;
513	
514	  // search again but now regardless of preferred numa affinity
515	  mi_forall_suitable_arenas(heap, req_arena, tseq, false /* numa non-matching now */, numa_node, allow_large, arena)
516	  {
517	    void* p = mi_arena_try_alloc_at(arena, slice_count, commit, tseq, memid);
518	    if (p != NULL) return p;
519	  }
520	  mi_forall_suitable_arenas_end();
521	  return NULL;
522	}
