572	// Allocate from the OS (if allowed)
573	static void* mi_arena_os_alloc_aligned(
574	  mi_subproc_t* subproc,
575	  size_t size, size_t alignment, size_t align_offset,
576	  bool commit, bool allow_large,
577	  mi_arena_id_t req_arena_id, mi_memid_t* memid)
578	{
579	  // if we cannot use OS allocation, return NULL
580	  if (mi_option_is_enabled(mi_option_disallow_os_alloc) || req_arena_id != _mi_arena_id_none()) {
581	    errno = ENOMEM;
582	    return NULL;
583	  }
584	
585	  if (align_offset > 0) {
586	    return _mi_os_alloc_aligned_at_offset(subproc, size, alignment, align_offset, commit, allow_large, memid);
587	  }
588	  else {
589	    return _mi_os_alloc_aligned(subproc, size, alignment, commit, allow_large, memid);
590	  }
591	}
