629	// release ownership of a page. This may free the page if all blocks were concurrently
630	// freed in the meantime. Returns true if the page was freed.
631	static bool mi_abandoned_page_unown(mi_page_t* page, mi_theap_t* current_theapx) {
632	  mi_assert_internal(mi_page_is_owned(page));
633	  mi_assert_internal(mi_page_is_abandoned(page));
634	  mi_assert_internal(mi_theap_matches_thread(current_theapx));
635	  mi_thread_free_t tf_new;
636	  mi_thread_free_t tf_old = mi_atomic_load_relaxed(&page->xthread_free);
637	  do {
638	    mi_assert_internal(mi_tf_is_owned(tf_old));
639	    while mi_unlikely(mi_tf_block(tf_old) != NULL) {
640	      _mi_page_free_collect(page, false);  // update used
641	      if (mi_page_all_free(page)) {        // it may become free just before unowning it
642	        _mi_arenas_page_unabandon(page, current_theapx);
643	        _mi_arenas_page_free(page, current_theapx);
644	        return true;
645	      }
646	      tf_old = mi_atomic_load_relaxed(&page->xthread_free);
647	    }
648	    mi_assert_internal(mi_tf_block(tf_old)==NULL);
649	    tf_new = mi_tf_create(NULL, false);
650	  } while (!mi_atomic_cas_weak_acq_rel(&page->xthread_free, &tf_old, tf_new));
651	  return false;
652	}
