674	// allocate initial arena_pages from the main heap
675	static mi_arena_pages_t* mi_arena_pages_alloc(mi_arena_t* arena);
676	
677	static mi_arena_pages_t* mi_heap_arena_pages(mi_heap_t* heap, mi_arena_t* arena) {
678	  mi_assert_internal(arena!=NULL);
679	  mi_assert_internal(heap!=NULL);
680	  mi_assert(arena->arena_idx < MI_MAX_ARENAS);
681	  return mi_atomic_load_ptr_acquire(mi_arena_pages_t, &heap->arena_pages[arena->arena_idx]);
682	}
