684	static mi_arena_t* mi_page_arena_pages(mi_page_t* page, size_t* slice_index, size_t* slice_count, mi_arena_pages_t** parena_pages) {
685	  // todo: maybe store the arena* directly in the page?
686	  mi_assert_internal(mi_page_is_owned(page));
687	  mi_arena_t* const arena = mi_arena_from_memid(page->memid, slice_index, slice_count);
688	  mi_assert_internal(arena != NULL);
689	  if (parena_pages != NULL) {
690	    mi_heap_t* heap = mi_page_heap(page);
691	    mi_arena_pages_t* const arena_pages = mi_heap_arena_pages(heap, arena);
692	    mi_assert_internal(arena_pages != NULL);
693	    mi_assert_internal(slice_index==NULL || mi_bitmap_is_set(arena_pages->pages, *slice_index));
694	    *parena_pages = arena_pages;
695	  }
696	  return arena;
697	}
