699	static mi_arena_pages_t* mi_heap_ensure_arena_pages(mi_heap_t* heap, mi_arena_t* arena) {
700	  mi_assert_internal(arena!=NULL);
701	  mi_assert_internal(heap!=NULL);
702	  mi_assert(arena->arena_idx < MI_MAX_ARENAS);
703	  mi_arena_pages_t* arena_pages = mi_heap_arena_pages(heap, arena);
704	  if (arena_pages==NULL) {
705	    mi_lock(&heap->arena_pages_lock) {
706	      arena_pages = mi_atomic_load_ptr_acquire(mi_arena_pages_t, &heap->arena_pages[arena->arena_idx]);
707	      if (arena_pages == NULL) {  // still NULL?
708	        if (_mi_is_heap_main(heap)) {
709	          // the page info for the main heap is always allocated as part of an arena
710	          arena_pages = &arena->pages_main;
711	        }
712	        else {
713	          // always allocate the arena pages info from the main heap
714	          // todo: allocate into the current arena?
715	          arena_pages = mi_arena_pages_alloc(arena);
716	        }
717	        mi_atomic_store_ptr_release(mi_arena_pages_t, &heap->arena_pages[arena->arena_idx], arena_pages);
718	      }
719	    }
720	  }
721	  if (_mi_is_heap_main(heap)) { mi_assert(arena_pages != NULL); }  // can never fail
722	  return arena_pages;
723	}
