725	static mi_page_t* mi_arenas_page_try_find_abandoned(mi_theap_t* theap, size_t slice_count, size_t block_size)
726	{
727	  mi_heap_t* const heap = _mi_theap_heap(theap);
728	  const size_t tseq = theap->tld->thread_seq;
729	  mi_arena_t* const req_arena = heap->exclusive_arena;
730	
731	  MI_UNUSED(slice_count);
732	  const size_t bin = _mi_bin(block_size);
733	  if (bin >= MI_ARENA_BIN_COUNT) {
734	    return NULL; // singleton page size
735	  }
736	
737	  // any abandoned in our size class?
738	  mi_assert_internal(heap != NULL);
739	  if (mi_atomic_load_relaxed(&heap->abandoned_count[bin]) == 0) {
740	    return NULL;
741	  }
742	
743	  // search arena's
744	  const bool allow_large = true;
745	  const int  any_numa = -1;
746	  const bool match_numa = true;
747	  mi_forall_suitable_arenas(heap, req_arena, tseq, match_numa, any_numa, allow_large, arena)
748	  {
749	    mi_arena_pages_t* const arena_pages = mi_heap_arena_pages(heap, arena);
750	    if (arena_pages != NULL) {
751	      size_t slice_index;
752	      mi_bitmap_t* const bitmap = arena_pages->pages_abandoned[bin];
753	
754	      if (mi_bitmap_try_find_and_claim(bitmap, tseq, &slice_index, &mi_arena_try_claim_abandoned, arena)) {
755	        // found an abandoned page of the right size
756	        // and claimed ownership.
757	        mi_page_t* page = mi_arena_page_at_slice(arena, slice_index);
758	        mi_assert_internal(mi_page_is_owned(page));
759	        mi_assert_internal(mi_page_is_abandoned(page));
760	        mi_assert_internal(mi_heap_has_page(heap, arena, page));
761	        mi_atomic_decrement_relaxed(&heap->abandoned_count[bin]);
762	        mi_theap_stat_decrease(theap, pages_abandoned, 1);
763	        mi_theap_stat_counter_increase(theap, pages_reclaim_on_alloc, 1);
764	
765	        _mi_page_free_collect(page, false);  // update `used` count
766	        mi_assert_internal(mi_bbitmap_is_clearN(arena->slices_free, slice_index, slice_count));
767	        mi_assert_internal(mi_page_slice_committed(page) > 0 || mi_bitmap_is_setN(arena->slices_committed, slice_index, slice_count));
768	        mi_assert_internal(mi_bitmap_is_setN(arena->slices_dirty, slice_index, slice_count));
769	        mi_assert_internal(_mi_is_aligned(mi_page_slice_start(page), MI_PAGE_ALIGN));
770	        mi_assert_internal(_mi_ptr_page(mi_page_start(page))==page);
771	        mi_assert_internal(mi_page_block_size(page) == block_size);
772	        mi_assert_internal(!mi_page_is_full(page));
773	        return page;
774	      }
775	    }
776	  }
777	  mi_forall_suitable_arenas_end();
778	  return NULL;
779	}
