781	static uint8_t* mi_arenas_page_alloc_fresh_area(mi_theap_t* theap, size_t slice_count, size_t max_page_meta_count, size_t block_alignment, bool os_align, bool commit, mi_memid_t* memid, mi_arena_pages_t** parena_pages ) {
782	  MI_UNUSED(max_page_meta_count);
783	  mi_assert_internal(parena_pages!=NULL);
784	
785	  *parena_pages = NULL;
786	  const bool allow_large = (MI_SECURE < 5); // 5 = guard page at end of each arena page
787	  const size_t page_alignment = MI_ARENA_SLICE_ALIGN;
788	
789	  mi_heap_t*  const heap = _mi_theap_heap(theap);
790	  mi_tld_t*   const tld  = theap->tld;
791	  mi_arena_t* const req_arena = heap->exclusive_arena;
792	  const int numa_node = (heap->numa_node >= 0 ? heap->numa_node : tld->numa_node);
793	
794	  // try to allocate from free space in arena's
795	  uint8_t* start = NULL;
796	  *memid = _mi_memid_none();
797	  const size_t alloc_size = mi_size_of_slices(slice_count);
798	  if (!mi_option_is_enabled(mi_option_disallow_arena_alloc) &&       // allowed to allocate from arena's?
799	      !os_align &&                                                   // not large alignment
800	      slice_count <= mi_arena_max_object_size()/MI_ARENA_SLICE_SIZE) // and not too large
801	  {
802	    start = (uint8_t*)mi_arenas_try_alloc(heap, slice_count, page_alignment, commit, allow_large, req_arena, tld->thread_seq, numa_node, memid);
803	    if (start != NULL) {
804	      mi_arena_pages_t* const arena_pages = mi_heap_ensure_arena_pages(heap, memid->mem.arena.arena);
805	      *parena_pages = arena_pages;
806	      if (arena_pages==NULL) {
807	        _mi_arenas_free(heap->subproc, start, mi_size_of_slices(slice_count), *memid); // roll back
808	        start = NULL;
809	      }
810	      else {
811	        // note: the following assert should hold if we could check it atomically, but in a concurrent setting we may already allocate in slice_count
812	        // mi_assert_internal(mi_bitmap_is_clearN(arena_pages->pages, memid->mem.arena.slice_index, memid->mem.arena.slice_count));
813	        mi_assert_internal(mi_bitmap_is_clear(arena_pages->pages, memid->mem.arena.slice_index));
814	        // don't set yet: mi_bitmap_set(arena_pages->pages, memid->mem.arena.slice_index);
815	      }
816	    }
817	  }
818	
819	  // otherwise fall back to the OS
820	  if (start == NULL) {
821	    #if MI_PAGE_META_IS_ALIGNED
822	    size_t page_offset;      // offset in the block for the page area
823	    uint8_t* os_start;
824	    if (block_alignment < MI_PAGE_META_ALIGNMENT) {          
825	      page_offset = (block_alignment < MI_PAGE_ALIGN ? MI_PAGE_ALIGN : block_alignment);
826	      os_start = (uint8_t*)mi_arena_os_alloc_aligned(heap->subproc, alloc_size + page_offset, MI_PAGE_META_ALIGNMENT, 0 /* align offset */, false /* commit */, false /* allow large */, req_arena, memid);
827	    }
828	    else {
829	      // if we allow alignment >= MI_PAGE_META_ALIGNMENT we need to substract 1 from a pointer
830	      // in _mi_aligned_ptr_page (and test for (intptr_t)p < 0 instead of NULL). We avoid this by limiting the max alignment.
831	      _mi_warning_message("requested alignment is too large (%zu KiB)\n", block_alignment / MI_KiB);
832	      errno = EINVAL;
833	      return NULL;
834	      // page_offset = MI_PAGE_META_ALIGNMENT;
835	      // os_start = (uint8_t*)mi_arena_os_alloc_aligned(heap->subproc, alloc_size + page_offset, block_alignment, MI_PAGE_META_ALIGNMENT /* align offset */, false /* commit */, false /* allow large */, req_arena, memid);
836	    }
837	    if (os_start==NULL) return NULL;
838	    // commit page info and page
839	    const size_t min_page_count = _mi_divide_up(page_offset + MI_ARENA_SLICE_SIZE,MI_ARENA_SLICE_SIZE) + max_page_meta_count;
840	    const size_t min_page_meta  = min_page_count * sizeof(mi_page_t);
841	    mi_assert_internal(min_page_meta < page_offset);
842	    bool is_zero;
843	    bool ok = mi_arena_commit(heap->subproc,req_arena,os_start,min_page_meta,&is_zero,min_page_meta /* don't count in stats? */);
844	    if (ok && commit) {
845	      ok = mi_arena_commit(heap->subproc,req_arena,os_start + page_offset,alloc_size,NULL,0);
846	    }
847	    if (!ok) { _mi_os_free(heap->subproc,os_start,alloc_size+page_offset,*memid); return NULL; }
848	    if (!is_zero && !memid->initially_zero) {
849	      _mi_memzero_aligned(os_start,min_page_meta);
850	    }
851	    start = os_start + page_offset;
852	    mi_assert_internal(_mi_is_aligned(start,block_alignment));
853	    mi_assert_internal(_mi_is_aligned(os_start,MI_PAGE_META_ALIGNMENT));
854	    mi_assert_internal(_mi_align_down_ptr(start-1,MI_PAGE_META_ALIGNMENT) == os_start);
855	    mi_assert_internal((uint8_t*)_mi_aligned_ptr_page0(start) < os_start + min_page_meta);
856	    memid->initially_committed = true; // so we don't commit again
857	    #else
858	    if (os_align) {
859	      // note: slice_count already includes the page
860	      start = (uint8_t*)mi_arena_os_alloc_aligned(heap->subproc, alloc_size, block_alignment, page_alignment /* align offset */, commit, allow_large, req_arena, memid);
861	      mi_assert_internal(_mi_is_aligned(start + page_alignment, block_alignment));
862	    }
863	    else {
864	      start = (uint8_t*)mi_arena_os_alloc_aligned(heap->subproc, alloc_size, page_alignment, 0 /* align offset */, commit, allow_large, req_arena, memid);
865	    }
866	    #endif
867	  }
868	
869	  if (start == NULL) return NULL;
870	  mi_assert_internal(_mi_is_aligned(start, MI_PAGE_ALIGN));
871	  return start;
872	}
