911	static mi_page_t* mi_arena_page_meta(mi_memid_t memid_slice, const void* slice_start) {
912	  #if MI_PAGE_META_IS_ALIGNED
913	  if (memid_slice.memkind == MI_MEM_ARENA || mi_memid_is_os(memid_slice)) {
914	    // ensure the meta data is committed
915	    if (memid_slice.memkind == MI_MEM_ARENA) {
916	      mi_arena_t* const arena    = memid_slice.mem.arena.arena;
917	      uint8_t* const meta_slices = (uint8_t*)_mi_align_down_ptr(slice_start,MI_PAGE_META_ALIGNMENT);
918	      mi_assert_internal(meta_slices >= mi_arena_start(arena));
919	      const size_t meta_slice_index  = (meta_slices - mi_arena_start(arena)) / MI_ARENA_SLICE_SIZE;
920	      if mi_unlikely(mi_bitmap_is_clear(arena->slices_committed, meta_slice_index)) {
921	        // try to commit all page meta slices now        
922	        const size_t meta_slice_count = mi_arena_page_meta_aligned_slice_count();
923	        // the following assertion does not hold in a concurrent setting..
924	        // mi_assert_internal(mi_bitmap_is_clearN(arena->slices_committed, meta_slice_index, meta_slice_count));
925	        const size_t commit_size = meta_slice_count * MI_ARENA_SLICE_SIZE;
926	        if (!mi_arena_commit(arena->subproc, arena, meta_slices, commit_size, NULL, 0)) {
927	          // if the commit fails return NULL
928	          return NULL;
929	        }
930	        // set the commit bits
931	        mi_bitmap_setN(arena->slices_committed, meta_slice_index, meta_slice_count, NULL);
932	      }
933	    }
934	    mi_page_t* const page_meta = _mi_aligned_ptr_page0(slice_start);
935	    return page_meta;
936	  }
937	  #else
938	  if (memid_slice.memkind == MI_MEM_ARENA) {
939	    MI_UNUSED(slice_start);
940	    mi_arena_t* const arena = memid_slice.mem.arena.arena;    
941	    if (arena->pages_meta != NULL) {
942	      mi_assert_internal(MI_PAGE_META_IS_SEPARATED!=0);        
943	      return &arena->pages_meta[memid_slice.mem.arena.slice_index];
944	    }
945	  }
946	  #endif
947	  return NULL;
948	}
