1129	// Allocate a regular small/medium/large page.
1130	static mi_page_t* mi_arenas_page_regular_alloc(mi_theap_t* theap, size_t slice_count, size_t block_size)
1131	{
1132	  // 1. look for an abandoned page
1133	  mi_page_t* page = mi_arenas_page_try_find_abandoned(theap, slice_count, block_size);
1134	  if (page != NULL) {
1135	    return page;  // return as abandoned
1136	  }
1137	
1138	  // 2. find a free block, potentially allocating a new arena
1139	  const long commit_on_demand = mi_option_get(mi_option_page_commit_on_demand);
1140	  const bool commit = (mi_page_min_commit_size() >= slice_count * MI_ARENA_SLICE_SIZE ||           // always commit small pages
1141	                       (slice_count >= mi_slice_count_of_size(UINT16_MAX * _mi_os_page_size())) ||   // always commit pages too large to hold a 32-bit slice_committed
1142	                        (commit_on_demand == 2 && _mi_os_has_overcommit()) || (commit_on_demand == 0));
1143	  page = mi_arenas_page_alloc_fresh(theap, slice_count, block_size, 1, commit);
1144	  if (page == NULL) return NULL;
1145	
1146	  mi_assert_internal(page->memid.memkind != MI_MEM_ARENA || page->memid.mem.arena.slice_count == slice_count);
1147	  if (!_mi_page_init(theap, page)) {
1148	    _mi_arenas_page_free(page,theap);
1149	    return NULL;
1150	  }
1151	
1152	  return page;
1153	}
