1155	// Allocate a page containing one block (very large, or with large alignment)
1156	static mi_page_t* mi_arenas_page_singleton_alloc(mi_theap_t* theap, size_t block_size, size_t block_alignment)
1157	{
1158	  #if MI_PAGE_META_IS_ALIGNED
1159	  const size_t info_size = 0;
1160	  #else
1161	  const bool os_align = (block_alignment > MI_PAGE_MAX_OVERALLOC_ALIGN);
1162	  const size_t info_size = (os_align ? MI_PAGE_ALIGN : mi_page_info_size());  
1163	  #endif
1164	  #if MI_SECURE < 2
1165	  const size_t slice_count = mi_slice_count_of_size(info_size + block_size);
1166	  #else
1167	  const size_t slice_count = mi_slice_count_of_size(_mi_align_up(info_size + block_size, _mi_os_secure_guard_page_size()) + _mi_os_secure_guard_page_size());
1168	  #endif
1169	
1170	  mi_page_t* page = mi_arenas_page_alloc_fresh(theap, slice_count, block_size, block_alignment, true /* commit singletons always */);
1171	  if (page == NULL) return NULL;
1172	
1173	  mi_assert(page->reserved == 1);
1174	  if (!_mi_page_init(theap, page)) {
1175	    _mi_arenas_page_free(page,theap);
1176	    return NULL;
1177	  }
1178	
1179	  return page;
1180	}
