1183	mi_page_t* _mi_arenas_page_alloc(mi_theap_t* theap, size_t block_size, size_t block_alignment) {
1184	  mi_page_t* page;
1185	  // semi static assert: ensure that all non-singleton block size bins are covered.
1186	  mi_assert(_mi_bin(MI_LARGE_MAX_OBJ_SIZE)  < MI_ARENA_BIN_COUNT);
1187	  if mi_unlikely(block_alignment > MI_PAGE_MAX_OVERALLOC_ALIGN) {
1188	    mi_assert_internal(_mi_is_power_of_two(block_alignment));
1189	    page = mi_arenas_page_singleton_alloc(theap, block_size, block_alignment);
1190	  }
1191	  else if (block_size <= MI_SMALL_MAX_OBJ_SIZE) {
1192	    page = mi_arenas_page_regular_alloc(theap, mi_slice_count_of_size(MI_SMALL_PAGE_SIZE), block_size);
1193	  }
1194	  else if (block_size <= MI_MEDIUM_MAX_OBJ_SIZE) {
1195	    page = mi_arenas_page_regular_alloc(theap, mi_slice_count_of_size(MI_MEDIUM_PAGE_SIZE), block_size);
1196	  }
1197	  #if MI_ENABLE_LARGE_PAGES
1198	  else if (block_size <= MI_LARGE_MAX_OBJ_SIZE) {
1199	    page = mi_arenas_page_regular_alloc(theap, mi_slice_count_of_size(MI_LARGE_PAGE_SIZE), block_size);
1200	  }
1201	  #endif
1202	  else {
1203	    page = mi_arenas_page_singleton_alloc(theap, block_size, block_alignment);
1204	  }
1205	  if mi_unlikely(page == NULL) {
1206	    return NULL;
1207	  }
1208	  // mi_assert_internal(page == NULL || _mi_page_segment(page)->subproc == tld->subproc);
1209	  mi_assert_internal(_mi_is_aligned(mi_page_slice_start(page), MI_PAGE_ALIGN));
1210	  mi_assert_internal(_mi_ptr_page(mi_page_start(page))==page);
1211	  mi_assert_internal(block_alignment <= MI_PAGE_MAX_OVERALLOC_ALIGN || _mi_is_aligned(mi_page_start(page), block_alignment));
1212	
1213	  return page;
1214	}
