1301	  Arena abandon
1302	----------------------------------------------------------- */
1303	
1304	void _mi_arenas_page_abandon(mi_page_t* page, mi_theap_t* current_theapx) {
1305	  mi_assert_internal(_mi_is_aligned(mi_page_slice_start(page), MI_PAGE_ALIGN));
1306	  mi_assert_internal(_mi_ptr_page(mi_page_start(page))==page);
1307	  mi_assert_internal(mi_page_is_owned(page));
1308	  mi_assert_internal(mi_page_is_abandoned(page));
1309	  mi_assert_internal(!mi_page_all_free(page));
1310	  mi_assert_internal(page->next==NULL && page->prev == NULL);
1311	  mi_assert_internal(mi_theap_matches_thread(current_theapx));
1312	  // mi_assert_internal(current_theap == _mi_page_associated_theap(page));
1313	
1314	  // add to abandoned?
1315	  mi_heap_t* heap = mi_page_heap(page);   
1316	  if (page->memid.memkind==MI_MEM_ARENA && !mi_page_is_full(page)) {
1317	    // make available for allocations
1318	    size_t bin = _mi_bin(mi_page_block_size(page));
1319	    mi_assert_internal(bin < MI_ARENA_BIN_COUNT);
1320	    if (bin < MI_ARENA_BIN_COUNT) { // paranoia
1321	      size_t slice_index;
1322	      size_t slice_count;
1323	      mi_arena_pages_t* arena_pages = NULL;
1324	      mi_arena_t* const arena = mi_page_arena_pages(page, &slice_index, &slice_count, &arena_pages); MI_UNUSED(arena);
1325	
1326	      mi_assert_internal(!mi_page_is_singleton(page));
1327	      mi_assert_internal(mi_bbitmap_is_clearN(arena->slices_free, slice_index, slice_count));
1328	      mi_assert_internal(mi_page_slice_committed(page) > 0 || mi_bitmap_is_setN(arena->slices_committed, slice_index, slice_count));
1329	      mi_assert_internal(mi_bitmap_is_setN(arena->slices_dirty, slice_index, slice_count));
1330	
1331	      mi_page_set_abandoned_mapped(page);
1332	      const bool was_clear = mi_bitmap_set(arena_pages->pages_abandoned[bin], slice_index);
1333	      MI_UNUSED(was_clear); mi_assert_internal(was_clear);
1334	      mi_atomic_increment_relaxed(&heap->abandoned_count[bin]);
1335	      mi_theapx_stat_increase(heap, current_theapx, pages_abandoned, 1);
1336	      mi_abandoned_page_unown(page, current_theapx);
1337	      return;
1338	    }
1339	  }
1340	  // otherwise,
1341	  // page is full (or a singleton), or the page is OS/externally allocated
1342	  // leave as is; it will be reclaimed when an object is free'd in the page
1343	  // but for non-arena pages, add to the subproc list so these can be visited
1344	  if (page->memid.memkind != MI_MEM_ARENA) {
1345	    mi_lock(&heap->os_abandoned_pages_lock) {
1346	      // push in front
1347	      page->prev = NULL;
1348	      page->next = heap->os_abandoned_pages;
1349	      if (page->next != NULL) { page->next->prev = page; }
1350	      heap->os_abandoned_pages = page;
1351	    }
1352	  }
1353	  mi_theapx_stat_increase(heap, current_theapx, pages_abandoned, 1);
1354	  mi_abandoned_page_unown(page, current_theapx);
1355	}
