1358	// this is called from `free.c:mi_free_try_collect_mt` only.
1359	bool _mi_arenas_page_try_reabandon_to_mapped(mi_page_t* page) {
1360	  mi_assert_internal(_mi_is_aligned(mi_page_slice_start(page), MI_PAGE_ALIGN));
1361	  mi_assert_internal(_mi_ptr_page(mi_page_start(page))==page);
1362	  mi_assert_internal(mi_page_is_owned(page));
1363	  mi_assert_internal(mi_page_is_abandoned(page));
1364	  mi_assert_internal(!mi_page_is_abandoned_mapped(page));
1365	  mi_assert_internal(!mi_page_is_full(page));
1366	  mi_assert_internal(!mi_page_all_free(page));
1367	  mi_assert_internal(!mi_page_is_singleton(page));
1368	  if (mi_page_is_full(page) || mi_page_is_abandoned_mapped(page) || page->memid.memkind != MI_MEM_ARENA) {
1369	    return false;
1370	  }
1371	  else {
1372	    // do not use _mi_heap_theap as we may call this during shutdown of threads and don't want to reinitialize the theap
1373	    mi_theap_t* const theapx = _mi_page_associated_theap_peek(page); // can be NULL
1374	    mi_heap_t* const heap = mi_page_heap(page);   
1375	    // if (theapx==NULL) return false;
1376	    mi_theapx_stat_counter_increase(heap, theapx, pages_reabandon_full, 1);
1377	    mi_theapx_stat_adjust_decrease(heap, theapx, pages_abandoned, 1);  // adjust as we are not abandoning fresh
1378	    _mi_arenas_page_abandon(page, theapx);
1379	    return true;
1380	  }
1381	}
