1383	// called from `mi_free` if trying to unabandon an abandoned page
1384	void _mi_arenas_page_unabandon(mi_page_t* page, mi_theap_t* current_theapx) {
1385	  mi_assert_internal(_mi_is_aligned(mi_page_slice_start(page), MI_PAGE_ALIGN));
1386	  mi_assert_internal(_mi_ptr_page(mi_page_start(page))==page);
1387	  mi_assert_internal(mi_page_is_owned(page));
1388	  mi_assert_internal(mi_page_is_abandoned(page));
1389	  mi_assert_internal(mi_theap_matches_thread(current_theapx));
1390	
1391	  mi_heap_t* const heap = mi_page_heap(page);
1392	  if (mi_page_is_abandoned_mapped(page)) {
1393	    mi_assert_internal(page->memid.memkind==MI_MEM_ARENA);
1394	    // remove from the abandoned map
1395	    const size_t bin = _mi_bin(mi_page_block_size(page));
1396	    mi_assert_internal(bin < MI_ARENA_BIN_COUNT);
1397	    size_t slice_index;
1398	    size_t slice_count;
1399	    mi_arena_pages_t* arena_pages;
1400	    mi_arena_t* arena = mi_page_arena_pages(page, &slice_index, &slice_count, &arena_pages);  MI_UNUSED(arena);
1401	
1402	    mi_assert_internal(mi_bbitmap_is_clearN(arena->slices_free, slice_index, slice_count));
1403	    mi_assert_internal(mi_page_slice_committed(page) > 0 || mi_bitmap_is_setN(arena->slices_committed, slice_index, slice_count));
1404	
1405	    // this busy waits until a concurrent reader (from alloc_abandoned) is done
1406	    mi_bitmap_clear_once_set(arena->subproc, arena_pages->pages_abandoned[bin], slice_index);
1407	    mi_page_clear_abandoned_mapped(page);
1408	    mi_atomic_decrement_relaxed(&heap->abandoned_count[bin]);
1409	  }
1410	  else {
1411	    // page is full (or a singleton), page is OS allocated
1412	    // if not an arena page, remove from the subproc os pages list
1413	    if (page->memid.memkind != MI_MEM_ARENA) {
1414	      mi_lock(&heap->os_abandoned_pages_lock) {
1415	        if (page->prev != NULL) { page->prev->next = page->next; }
1416	        if (page->next != NULL) { page->next->prev = page->prev; }
1417	        if (heap->os_abandoned_pages == page) { heap->os_abandoned_pages = page->next; }
1418	        page->next = NULL;
1419	        page->prev = NULL;
1420	      }
1421	    }
1422	  }
1423	  mi_theapx_stat_decrease(heap, current_theapx, pages_abandoned, 1);
1424	}
