1498	// Is a pointer contained in the given arena area?
1499	static bool mi_arena_strictly_contains(mi_arena_t* arena, const void* p) {
1500	  return (arena != NULL &&
1501	          mi_arena_start(arena) <= (const uint8_t*)p &&
1502	          mi_arena_start(arena) + mi_size_of_slices(arena->slice_count) >(const uint8_t*)p);
1503	}
