1505	// Is a pointer inside any of our arenas?
1506	static bool mi_arenas_contain_ex(const void* p, mi_arena_t* parent) {
1507	  mi_subproc_t* subproc = _mi_subproc();
1508	  const size_t max_arena = mi_arenas_get_count(subproc);
1509	  for (size_t i = 0; i < max_arena; i++) {
1510	    mi_arena_t* arena = mi_atomic_load_ptr_acquire(mi_arena_t, &subproc->arenas[i]);
1511	    if (arena != NULL) {
1512	      if (parent==NULL || arena==parent || arena->parent==parent) {
1513	        if (mi_arena_strictly_contains(arena, p)) {
1514	          return true;
1515	        }
1516	      }
1517	    }
1518	  }
1519	  return false;
1520	}
