1527	// Is a pointer contained in the given arena area?
1528	bool mi_arena_contains(mi_arena_id_t arena_id, const void* p) {
1529	  mi_arena_t* arena = _mi_arena_from_id(arena_id);
1530	  if (arena==NULL) return false;
1531	  else if (mi_arena_strictly_contains(arena, p)) return true;
