1562	// for dynamic libraries that are unloaded and need to release all their allocated memory.
1563	void _mi_arenas_unsafe_destroy_all(mi_subproc_t* subproc) {
1564	  mi_arenas_unsafe_destroy(subproc);
1565	  // mi_arenas_try_purge(true /* force purge */, true /* visit all*/, subproc, 0 /* thread seq */);  // purge non-owned arenas
1566	}
