1569	/* -----------------------------------------------------------
1570	  Add an arena.
1571	----------------------------------------------------------- */
1572	
1573	static bool mi_arenas_add(mi_subproc_t* subproc, mi_arena_t* arena, mi_arena_id_t* arena_id)
1574	{
1575	  mi_assert_internal(arena != NULL);
1576	  mi_assert_internal(arena->slice_count > 0);
1577	  if (arena_id != NULL) { *arena_id = _mi_arena_id_none(); }
1578	
1579	  // try to find a NULL entry
1580	  mi_arena_t* expected;
1581	  size_t count = mi_arenas_get_count(subproc);
1582	  for( size_t i = 0; i < count; i++) {
1583	    if (mi_arena_from_index(subproc,i) == NULL) {
1584	      arena->arena_idx = i;
1585	      expected = NULL;
1586	      if (mi_atomic_cas_ptr_strong_release(mi_arena_t, &subproc->arenas[i], &expected, arena)) {
1587	        // success
1588	        if (arena_id != NULL) { *arena_id = mi_arena_id_from_arena(arena); }
1589	        return true;
1590	      }
1591	    }
1592	  }
1593	
1594	  // otherwise, try to allocate a fresh slot
1595	  while(count<MI_MAX_ARENAS) {
1596	    if (mi_atomic_cas_strong_release(&subproc->arena_count, &count, count+1)) {
1597	      arena->arena_idx = count;
1598	      expected = NULL;
1599	      if (mi_atomic_cas_ptr_strong_release(mi_arena_t, &subproc->arenas[count], &expected, arena)) {
1600	        mi_subproc_stat_counter_increase(arena->subproc, arena_count, 1);
1601	        if (arena_id != NULL) { *arena_id = mi_arena_id_from_arena(arena); }
1602	        return true;
1603	      }
1604	    }
1605	  }
1606	
1607	  // failed
1608	  arena->arena_idx = 0;
1609	  arena->subproc = NULL;
1610	  return false;
1611	}
