1613	static size_t mi_arena_pages_size(size_t slice_count, size_t* bitmap_base) {
1614	  if (slice_count == 0) slice_count = MI_BCHUNK_BITS;
1615	  mi_assert_internal((slice_count % MI_BCHUNK_BITS) == 0);
1616	  const size_t base_size = _mi_align_up(sizeof(mi_arena_pages_t), MI_BCHUNK_SIZE);
1617	  const size_t bitmaps_count = 1 + MI_ARENA_BIN_COUNT; // pages, and abandoned
1618	  const size_t bitmaps_size = bitmaps_count * mi_bitmap_size(slice_count, NULL);
1619	  const size_t size = base_size + bitmaps_size;
1620	  if (bitmap_base != NULL) *bitmap_base = base_size;
1621	  return size;
1622	}
1623	
1624	static mi_arena_t* mi_arena_info(void* area) {
1625	  return (mi_arena_t*)((uint8_t*)area + mi_size_of_slices(mi_arena_page_meta_aligned_slice_count()));
1626	}
1627	
1628	static size_t mi_arena_info_slices_needed(size_t slice_count, size_t* bitmap_base) {
1629	  if (slice_count == 0) slice_count = MI_BCHUNK_BITS;
1630	  mi_assert_internal((slice_count % MI_BCHUNK_BITS) == 0);
1631	  const size_t base_size = mi_size_of_slices(mi_arena_page_meta_aligned_slice_count()) + _mi_align_up(sizeof(mi_arena_t), MI_BCHUNK_SIZE);
1632	  const size_t bitmaps_count = 4 + MI_ARENA_BIN_COUNT; // commit, dirty, purge, pages, and abandoned
1633	  const size_t bitmaps_size = bitmaps_count * mi_bitmap_size(slice_count, NULL) + mi_bbitmap_size(slice_count, NULL); // + free
1634	  #if MI_PAGE_META_IS_SEPARATED && !MI_PAGE_META_IS_ALIGNED
1635	  const size_t pages_size = slice_count * sizeof(mi_page_t);
1636	  #else
1637	  const size_t pages_size = 0;
1638	  #endif
1639	  const size_t size = base_size + bitmaps_size + pages_size;
1640	
1641	  const size_t os_page_size = _mi_os_page_size();
1642	  const size_t info_size = _mi_align_up(size, os_page_size) + _mi_os_secure_guard_page_size();
1643	  const size_t info_slices = mi_slice_count_of_size(info_size);
1644	
1645	  if (bitmap_base != NULL) *bitmap_base = base_size;
1646	  return info_slices;
1647	}
1648	
1649	static mi_bitmap_t* mi_arena_bitmap_init(size_t slice_count, uint8_t** base) {
1650	  mi_bitmap_t* bitmap = (mi_bitmap_t*)(*base);
1651	  *base = (*base) + mi_bitmap_init(bitmap, slice_count, true /* already zero */);
1652	  return bitmap;
1653	}
1654	
1655	static mi_bbitmap_t* mi_arena_bbitmap_init(mi_subproc_t* subproc, size_t slice_count, uint8_t** base) {
1656	  mi_bbitmap_t* bbitmap = (mi_bbitmap_t*)(*base);
1657	  *base = (*base) + mi_bbitmap_init(subproc, bbitmap, slice_count, true /* already zero */);
1658	  return bbitmap;
1659	}
1660	
1661	static mi_arena_pages_t* mi_arena_pages_alloc(mi_arena_t* arena) {
1662	  const size_t slice_count = arena->slice_count;
1663	  size_t bitmap_base = 0;
1664	  const size_t size = mi_arena_pages_size(slice_count, &bitmap_base);
1665	  mi_arena_pages_t* arena_pages = (mi_arena_pages_t*)mi_heap_zalloc_aligned(arena->subproc->heap_main, size, MI_BCHUNK_SIZE);
1666	  if (arena_pages==NULL) return NULL;
1667	  uint8_t* base = (uint8_t*)arena_pages + bitmap_base;
1668	  mi_assert_internal(_mi_is_aligned(base, MI_BCHUNK_SIZE));
1669	  arena_pages->pages = mi_arena_bitmap_init(slice_count, &base);
1670	  for (size_t i = 0; i < MI_ARENA_BIN_COUNT; i++) {
1671	    arena_pages->pages_abandoned[i] = mi_arena_bitmap_init(slice_count, &base);
1672	  }
1673	  return arena_pages;
1674	}
1675	
1676	static mi_arena_t* mi_arena_initialize(mi_subproc_t* subproc, void* start,
1677	                                        size_t slice_count, mi_arena_t* parent, size_t total_size,
1678	                                        int numa_node, bool exclusive,
1679	                                        mi_memid_t memid, mi_commit_fun_t* commit_fun, void* commit_fun_arg, mi_arena_id_t* arena_id)
1680	{
1681	  mi_assert_internal(_mi_is_aligned(start,MI_ARENA_ALIGNMENT));
1682	  mi_assert_internal(mi_size_of_slices(slice_count)>=MI_ARENA_MIN_SIZE);
1683	
1684	  if (slice_count > MI_BITMAP_MAX_BIT_COUNT) {  // 16 GiB for now
1685	    // note: this should never happen if called from `mi_manage_os_memory` (as that allocates sub-arenas when needed)
1686	    _mi_warning_message("cannot use OS memory since it is too large (size %zu MiB, maximum is %zu MiB)", mi_size_of_slices(slice_count)/MI_MiB, mi_size_of_slices(MI_BITMAP_MAX_BIT_COUNT)/MI_MiB);
1687	    return NULL;
1688	  }
1689	
1690	  size_t bitmap_base;
1691	  const size_t info_slices = mi_arena_info_slices_needed(slice_count, &bitmap_base);
1692	  if (slice_count < info_slices+1) {
1693	    _mi_warning_message("cannot use OS memory since it is not large enough (size %zu KiB, minimum required is %zu KiB)", mi_size_of_slices(slice_count)/MI_KiB, mi_size_of_slices(info_slices+1)/MI_KiB);
1694	    return NULL;
1695	  }
1696	  // else if (info_slices >= MI_ARENA_MAX_CHUNK_OBJ_SLICES) {
1697	  //   _mi_warning_message("cannot use OS memory since it is too large with respect to the maximum object size (size %zu MiB, meta-info slices %zu, maximum object slices are %zu)", mi_size_of_slices(slice_count)/MI_MiB, info_slices, MI_ARENA_MAX_CHUNK_OBJ_SLICES);
1698	  //   return NULL;
1699	  // }
1700	  
1701	  // commit & zero if needed
1702	  if (!memid.initially_committed) {
1703	    size_t commit_size = mi_size_of_slices(info_slices);
1704	    // leave a guard OS page decommitted at the end?
1705	    if (!memid.is_pinned) { commit_size -= _mi_os_secure_guard_page_size(); }
1706	    bool ok = false;
1707	    if (commit_fun != NULL) {
1708	      ok = (*commit_fun)(true /* commit */, start, commit_size, NULL, commit_fun_arg);
1709	    }
1710	    else {
1711	      ok = _mi_os_commit(subproc, start, commit_size, NULL);
1712	    }
1713	    if (!ok) {
1714	      _mi_warning_message("unable to commit meta-data for OS memory");
1715	      return NULL;
1716	    }
1717	  }
1718	  else if (!memid.is_pinned) {
1719	    // if MI_SECURE, set a guard page at the end of the arena info
1720	    // todo: this does not respect the commit_fun as the memid is of external memory
1721	    _mi_os_secure_guard_page_set_before(subproc, (uint8_t*)start + mi_size_of_slices(info_slices), memid);
1722	  }
1723	  if (!memid.initially_zero) {
1724	    _mi_memzero(start, mi_size_of_slices(info_slices) - _mi_os_secure_guard_page_size());
1725	  }
1726	
1727	  // init
1728	  mi_arena_t* arena = mi_arena_info(start);
1729	  arena->start = start;
1730	  arena->subproc = subproc;
1731	  arena->memid = memid;
1732	  arena->is_exclusive = exclusive;
1733	  arena->slice_count = slice_count;
1734	  arena->info_slices = info_slices;
1735	  if (numa_node<0 && mi_option_is_enabled(mi_option_arena_is_numa_local)) {
1736	    arena->numa_node = _mi_os_numa_node();
1737	  }
1738	  else {
1739	    arena->numa_node = numa_node;
1740	  }
1741	  arena->purge_expire = 0;
1742	  arena->commit_fun = commit_fun;
1743	  arena->commit_fun_arg = commit_fun_arg;
1744	  arena->parent = parent;
1745	  arena->total_size = total_size;
1746	
1747	  // init bitmaps
1748	  uint8_t* base = mi_arena_start(arena) + bitmap_base;
1749	  arena->slices_free = mi_arena_bbitmap_init(subproc, slice_count, &base);
1750	  arena->slices_committed = mi_arena_bitmap_init(slice_count, &base);
1751	  arena->slices_dirty = mi_arena_bitmap_init(slice_count, &base);
1752	  arena->slices_purge = mi_arena_bitmap_init(slice_count, &base);
1753	  arena->pages_main.pages = mi_arena_bitmap_init(slice_count, &base);
1754	  for (size_t i = 0; i < MI_ARENA_BIN_COUNT; i++) {
1755	    arena->pages_main.pages_abandoned[i] = mi_arena_bitmap_init(slice_count, &base);
1756	  }
1757	  #if MI_PAGE_META_IS_SEPARATED && !MI_PAGE_META_IS_ALIGNED
1758	  arena->pages_meta = (mi_page_t*)base;
1759	  base += (slice_count * sizeof(mi_page_t));
1760	  #else
1761	  arena->pages_meta = NULL;
1762	  #endif
1763	  mi_assert_internal(mi_size_of_slices(info_slices) >= (size_t)(base - mi_arena_start(arena)));
1764	
1765	  // reserve our meta info (and reserve slices outside the memory area)
1766	  #if MI_PAGE_META_IS_ALIGNED
1767	  for(size_t i = 0; i < arena->slice_count; i += MI_PAGE_META_ALIGNED_COUNT) {
1768	    // set all free slices (and skip the slices reserved for the page meta info)
1769	    const size_t meta_slices = (i==0 ? info_slices : mi_arena_page_meta_aligned_slice_count());
1770	    const size_t start_idx = (i + meta_slices);
1771	    size_t count = MI_PAGE_META_ALIGNED_COUNT - meta_slices;
1772	    if (start_idx < arena->slice_count) {
1773	      if (count + start_idx > arena->slice_count) { 
1774	        count = arena->slice_count - start_idx;
1775	        mi_assert_internal(count > 0);
1776	      }
1777	      mi_bbitmap_unsafe_setN(arena->slices_free, start_idx, count);
1778	    }
1779	  }  
1780	  #else
1781	  mi_bbitmap_unsafe_setN(arena->slices_free, info_slices /* start */, arena->slice_count - info_slices);
1782	  #endif  
1783	  if (memid.initially_committed) {
1784	    mi_bitmap_unsafe_setN(arena->slices_committed, 0, arena->slice_count);
1785	  }
1786	  if (!memid.initially_zero) {
1787	    mi_bitmap_unsafe_setN(arena->slices_dirty, 0, arena->slice_count);
1788	  }
1789	
1790	  if (!mi_arenas_add(subproc, arena, arena_id)) { return NULL;  }
1791	  return arena;
1792	}
1793	
1794	static bool mi_manage_os_memory_ex2(mi_subproc_t* subproc, void* start, size_t size, int numa_node, bool exclusive,
1795	  mi_memid_t memid, mi_commit_fun_t* commit_fun, void* commit_fun_arg, mi_arena_id_t* arena_id) mi_attr_noexcept
1796	{
1797	  // checks
1798	  mi_assert(start!=NULL);
1799	  if (arena_id != NULL) { *arena_id = _mi_arena_id_none(); }
1800	  if (start==NULL) return false;
1801	  if (!_mi_is_aligned(start, MI_ARENA_ALIGNMENT)) {
1802	    // we can align the start since the memid tracks the real base of the memory.
1803	    void* const aligned_start = _mi_align_up_ptr(start, MI_ARENA_ALIGNMENT);
1804	    const size_t diff = (uint8_t*)aligned_start - (uint8_t*)start;
1805	    if (diff >= size || (size - diff) < MI_ARENA_ALIGNMENT) {
1806	      _mi_warning_message("after alignment, the size of the arena becomes too small (memory at %p with size %zu)\n", start, size);
1807	      return false;
1808	    }
1809	    start = aligned_start;
1810	    size = size - diff;
1811	  }
1812	
1813	  // allocate enough arena's to span the full memory area
1814	  // the first arena is the owner, the rest are "sub-arena" (with `parent` pointing to the first one)
1815	  size_t total_slice_count = _mi_align_down(size / MI_ARENA_SLICE_SIZE, MI_BCHUNK_BITS);
1816	  size_t total_size = mi_size_of_slices(total_slice_count);
