132	// `already_set` contains the count of bits that were already set (used when committing ranges to account
133	// statistics correctly).
134	static inline bool mi_bfield_atomic_set_mask(_Atomic(mi_bfield_t)*b, mi_bfield_t mask, size_t* already_set) {
135	  mi_assert_internal(mask != 0);
136	  const mi_bfield_t old = mi_atomic_or_acq_rel(b,mask);
137	  if (already_set!=NULL) { *already_set = mi_bfield_popcount(old&mask); }
138	  return ((old&mask) == 0);
139	}
140	
141	// Clear a mask set of bits atomically, and return true of the mask bits transitioned from all 1's to 0's
142	// `all_clear` is set to `true` if the new bfield became zero.
143	static inline bool mi_bfield_atomic_clear_mask(_Atomic(mi_bfield_t)*b, mi_bfield_t mask, bool* all_clear) {
144	  mi_assert_internal(mask != 0);
145	  const mi_bfield_t old = mi_atomic_and_acq_rel(b,~mask);  
146	  if (all_clear != NULL) { *all_clear = ((old&~mask)==0); }
147	  return ((old&mask) == mask);
148	}
149	
150	static inline bool mi_bfield_atomic_setX(_Atomic(mi_bfield_t)*b, size_t* already_set) {
151	  const mi_bfield_t old = mi_atomic_exchange_release(b, mi_bfield_all_set());
152	  if (already_set!=NULL) { *already_set = mi_bfield_popcount(old); }
153	  return (old==0);
154	}
155	
156	
157	// ------- mi_bfield_atomic_try_clear ---------------------------------------
158	
159	// Tries to clear a mask atomically, and returns true if the mask bits atomically transitioned from mask to 0
160	// and false otherwise (leaving the bit field as is). Returns the acquired value back in `expect` (regardless of success).
161	// `all_clear` is set to `true` if the new bfield became zero.
162	// `did_temp_clear_bits` is set to `true` some bits were temporarily cleared.
163	static inline bool mi_bfield_atomic_try_clear_mask_optimistic(_Atomic(mi_bfield_t)*b, mi_bfield_t mask, mi_bfield_t* previous, bool* did_temp_clear_bits) {
164	  mi_assert_internal(mask != 0);
165	  // note: we could also use a strong cas but generally an optimistic atomic and/or is more efficient (at least on arm64)
166	  // try to atomically clear the mask bits
167	  mi_bfield_t old = mi_atomic_and_acq_rel(b,~mask);
168	  if (previous!=NULL) { *previous = old; }    
169	  if mi_likely((old&mask)==mask) {
170	    // all bits in the mask transitioned from 1 to 0 atomically
171	    return true;
172	  }
173	  else {
174	    // failed to transition all
175	    if ((old&mask)!=0) {
176	      // restore accidentally cleared ones
177	      mi_atomic_or_acq_rel(b, old&mask);
178	      if (did_temp_clear_bits!=NULL) { *did_temp_clear_bits = true; }      
179	    }
180	    return false;
181	  }
182	}
183	
184	// Tries to clear a bit atomically. For performance, it assumes there is a good chance of success. 
185	// Returns `true` if the bit transitioned from 1 to 0
186	// and `false` otherwise (leaving the bfield `b` as-is).
187	// `all_clear` is set to true if the new bfield became zero (and false otherwise)
188	mi_decl_maybe_unused static inline bool mi_bfield_atomic_try_clear_optimistic(_Atomic(mi_bfield_t)* b, size_t idx, mi_bfield_t* previous) {
189	  mi_assert_internal(idx < MI_BFIELD_BITS);
190	  const mi_bfield_t mask = ((mi_bfield_t)1<<idx);
191	  return mi_bfield_atomic_try_clear_mask_optimistic(b, mask, previous, NULL);  // single bit never clears temporarily
192	}
193	
194	// Tries to clear a byte atomically. For performance, it assumes there is a good chance of success.  
195	// Returns true if the byte atomically transitioned from 0xFF to 0
196	// `all_clear` is set to true if the new bfield became zero (and false otherwise)
197	mi_decl_maybe_unused static inline bool mi_bfield_atomic_try_clear8_optimistic(_Atomic(mi_bfield_t)*b, size_t idx, mi_bfield_t* previous, bool* did_temp_clear_bits) {
198	  mi_assert_internal(idx < MI_BFIELD_BITS);
199	  mi_assert_internal((idx%8)==0);
200	  const mi_bfield_t mask = ((mi_bfield_t)0xFF)<<idx;
201	  return mi_bfield_atomic_try_clear_mask_optimistic(b, mask, previous, did_temp_clear_bits);
202	}
203	
204	// Try to clear a mask of bits atomically. For performance, it assumes these is a good chance of success. 
205	// Returns true all bits transitioned from all 1's to 0's.
206	// and false otherwise leaving the bit field as-is. `all_clear` is set to true if the new bfield became zero.
207	static inline bool mi_bfield_atomic_try_clear_mask(_Atomic(mi_bfield_t)* b, mi_bfield_t mask, bool* all_clear, bool* did_temp_clear_bits) {
208	  mi_assert_internal(mask != 0);
209	  mi_bfield_t old = mi_atomic_load_relaxed(b);  // check first if there is a good chance the mask bits are all set
210	  bool cleared = false;
211	  if ((old&mask)==mask) {  
212	    cleared = mi_bfield_atomic_try_clear_mask_optimistic(b, mask, &old, did_temp_clear_bits);
213	  }
214	  if (all_clear != NULL) { *all_clear = ((cleared ? old&~mask : old) == 0); }
215	  return cleared;
216	}
217	
218	// Try to clear a full field of bits atomically, and return true all bits transitioned from all 1's to 0's.
219	// and false otherwise leaving the bit field as-is.
220	// `all_clear` is set to true if the new bfield became zero (which is always the case if successful).
221	static inline bool mi_bfield_atomic_try_clearX(_Atomic(mi_bfield_t)*b, bool* all_clear) {
222	  mi_bfield_t old = mi_atomic_load_relaxed(b);  // check first if there is a good chance the bits are all set
223	  bool cleared = false;
224	  if (old==mi_bfield_all_set()) {
225	    cleared = mi_atomic_cas_strong_acq_rel(b,&old,mi_bfield_zero());
226	  }
227	  if (all_clear != NULL) { *all_clear = (cleared ? true : (old==0)); }
228	  return cleared;
229	}
230	
231	
232	// ------- mi_bfield_atomic_is_set ---------------------------------------
233	
234	// Check if a bit is set
235	static inline bool mi_bfield_atomic_is_set(const _Atomic(mi_bfield_t)*b, const size_t idx) {
236	  const mi_bfield_t x = mi_atomic_load_acquire(b);
237	  return ((x & mi_bfield_mask(1,idx)) != 0);
238	}
239	
240	// Check if a bit is clear
241	static inline bool mi_bfield_atomic_is_clear(const _Atomic(mi_bfield_t)*b, const size_t idx) {
242	  const mi_bfield_t x = mi_atomic_load_acquire(b);
243	  return ((x & mi_bfield_mask(1, idx)) == 0);
244	}
245	
246	// Check if a bit is xset
247	static inline bool mi_bfield_atomic_is_xset(mi_xset_t set, const _Atomic(mi_bfield_t)*b, const size_t idx) {
248	  if (set) return mi_bfield_atomic_is_set(b, idx);
249	      else return mi_bfield_atomic_is_clear(b, idx);
250	}
251	
252	// Check if all bits corresponding to a mask are set.
253	static inline bool mi_bfield_atomic_is_set_mask(const _Atomic(mi_bfield_t)* b, mi_bfield_t mask) {
254	  mi_assert_internal(mask != 0);
255	  const mi_bfield_t x = mi_atomic_load_acquire(b);
256	  return ((x & mask) == mask);
257	}
258	
259	// Check if all bits corresponding to a mask are clear.
260	static inline bool mi_bfield_atomic_is_clear_mask(const _Atomic(mi_bfield_t)* b, mi_bfield_t mask) {
261	  mi_assert_internal(mask != 0);
262	  const mi_bfield_t x = mi_atomic_load_acquire(b);
263	  return ((x & mask) == 0);
264	}
265	
266	// Check if all bits corresponding to a mask are set/cleared.
267	static inline bool mi_bfield_atomic_is_xset_mask(mi_xset_t set, const _Atomic(mi_bfield_t)* b, mi_bfield_t mask) {
268	  mi_assert_internal(mask != 0);
269	  if (set) return mi_bfield_atomic_is_set_mask(b, mask);
270	      else return mi_bfield_atomic_is_clear_mask(b, mask);
271	}
272	
273	// Count bits in a mask
274	static inline size_t mi_bfield_atomic_popcount_mask(_Atomic(mi_bfield_t)*b, mi_bfield_t mask) {
275	  const mi_bfield_t x = mi_atomic_load_acquire(b);
276	  return mi_bfield_popcount(x & mask);
277	}
278	
279	
280	/* --------------------------------------------------------------------------------
281	 bitmap chunks
282	-------------------------------------------------------------------------------- */
283	
284	// ------- mi_bchunk_set ---------------------------------------
285	
286	// Set a single bit
287	static inline bool mi_bchunk_set(mi_bchunk_t* chunk, size_t cidx, size_t* already_set) {
288	  mi_assert_internal(cidx < MI_BCHUNK_BITS);
289	  const size_t i = cidx / MI_BFIELD_BITS;
290	  const size_t idx = cidx % MI_BFIELD_BITS;
291	  const bool was_clear = mi_bfield_atomic_set(&chunk->bfields[i], idx);
292	  if (already_set != NULL) { *already_set = (was_clear ? 0 : 1); }
293	  return was_clear;
294	}
295	
296	// Set `0 < n <= MI_BFIELD_BITS`, and return true of the mask bits transitioned from all 0's to 1's.
297	// `already_set` contains the count of bits that were already set (used when committing ranges to account
298	// statistics correctly).
299	// Can cross over two bfields.
300	static inline bool mi_bchunk_setNX(mi_bchunk_t* chunk, size_t cidx, size_t n, size_t* already_set) {
301	  mi_assert_internal(cidx < MI_BCHUNK_BITS);
302	  mi_assert_internal(n > 0 && n <= MI_BFIELD_BITS);
303	  const size_t i = cidx / MI_BFIELD_BITS;
304	  const size_t idx = cidx % MI_BFIELD_BITS;
305	  if mi_likely(idx + n <= MI_BFIELD_BITS) {
306	    // within one field
307	    return mi_bfield_atomic_set_mask(&chunk->bfields[i], mi_bfield_mask(n,idx), already_set);
308	  }
309	  else {
310	    // spanning two fields
311	    const size_t m = MI_BFIELD_BITS - idx;  // bits to clear in the first field
312	    mi_assert_internal(m < n);
313	    mi_assert_internal(i < MI_BCHUNK_FIELDS - 1);
314	    mi_assert_internal(idx + m <= MI_BFIELD_BITS);
315	    size_t already_set1;
316	    const bool all_set1 = mi_bfield_atomic_set_mask(&chunk->bfields[i], mi_bfield_mask(m, idx), &already_set1);
317	    mi_assert_internal(n - m > 0);
318	    mi_assert_internal(n - m < MI_BFIELD_BITS);
319	    size_t already_set2;
320	    const bool all_set2 = mi_bfield_atomic_set_mask(&chunk->bfields[i+1], mi_bfield_mask(n - m, 0), &already_set2);
321	    if (already_set != NULL) { *already_set = already_set1 + already_set2; }
322	    return (all_set1 && all_set2);
323	  }
324	}
325	
326	// Set a sequence of `n` bits within a chunk.
327	// Returns true if all bits transitioned from 0 to 1 (or 1 to 0).
328	mi_decl_noinline static bool mi_bchunk_xsetNC(mi_xset_t set, mi_bchunk_t* chunk, size_t cidx, size_t n, size_t* palready_set, bool* pmaybe_all_clear) {
329	  mi_assert_internal(cidx + n <= MI_BCHUNK_BITS);
330	  mi_assert_internal(n>0);
331	  bool all_transition = true;
332	  bool maybe_all_clear = true;
333	  size_t total_already_set = 0;
334	  size_t idx   = cidx % MI_BFIELD_BITS;
335	  size_t field = cidx / MI_BFIELD_BITS;
336	  while (n > 0) {
337	    size_t m = MI_BFIELD_BITS - idx;   // m is the bits to xset in this field
338	    if (m > n) { m = n; }
339	    mi_assert_internal(idx + m <= MI_BFIELD_BITS);
340	    mi_assert_internal(field < MI_BCHUNK_FIELDS);
341	    const mi_bfield_t mask = mi_bfield_mask(m, idx);
342	    size_t already_set = 0;
343	    bool all_clear = false;
344	    const bool transition = (set ? mi_bfield_atomic_set_mask(&chunk->bfields[field], mask, &already_set)
345	                                 : mi_bfield_atomic_clear_mask(&chunk->bfields[field], mask, &all_clear));
346	    mi_assert_internal(!set || ((transition && already_set == 0) || (!transition && already_set > 0)));
347	    all_transition = all_transition && transition;
348	    total_already_set += already_set;
349	    maybe_all_clear = maybe_all_clear && all_clear;
350	    // next field
351	    field++;
352	    idx = 0;
353	    mi_assert_internal(m <= n);
354	    n -= m;
355	  }
356	  if (palready_set!=NULL) { *palready_set = total_already_set; }
357	  if (pmaybe_all_clear!=NULL) { *pmaybe_all_clear = maybe_all_clear; }
358	  return all_transition;
359	}
360	
361	static inline bool mi_bchunk_setN(mi_bchunk_t* chunk, size_t cidx, size_t n, size_t* already_set) {
362	  mi_assert_internal(n>0 && n <= MI_BCHUNK_BITS);
363	  if (n==1) return mi_bchunk_set(chunk, cidx, already_set);
364	  // if (n==8 && (cidx%8) == 0) return mi_bchunk_set8(chunk, cidx, already_set);
365	  // if (n==MI_BFIELD_BITS) return mi_bchunk_setX(chunk, cidx, already_set);
366	  if (n<=MI_BFIELD_BITS) return mi_bchunk_setNX(chunk, cidx, n, already_set);
367	  return mi_bchunk_xsetNC(MI_BIT_SET, chunk, cidx, n, already_set, NULL);
368	}
369	
370	// ------- mi_bchunk_clear ---------------------------------------
371	
372	static inline bool mi_bchunk_clear(mi_bchunk_t* chunk, size_t cidx, bool* all_clear) {
373	  mi_assert_internal(cidx < MI_BCHUNK_BITS);
374	  const size_t i = cidx / MI_BFIELD_BITS;
375	  const size_t idx = cidx % MI_BFIELD_BITS;
376	  return mi_bfield_atomic_clear(&chunk->bfields[i], idx, all_clear);
377	}
378	
379	static inline bool mi_bchunk_clearN(mi_bchunk_t* chunk, size_t cidx, size_t n, bool* maybe_all_clear) {
380	  mi_assert_internal(n>0 && n <= MI_BCHUNK_BITS);
381	  if (n==1) return mi_bchunk_clear(chunk, cidx, maybe_all_clear);
382	  // if (n==8) return mi_bchunk_clear8(chunk, cidx, maybe_all_clear);
383	  // if (n==MI_BFIELD_BITS) return mi_bchunk_clearX(chunk, cidx, maybe_all_clear);
384	  // todo: implement mi_bchunk_xsetNX instead of setNX
385	  return mi_bchunk_xsetNC(MI_BIT_CLEAR, chunk, cidx, n, NULL, maybe_all_clear);
386	}
387	
388	// Check if a sequence of `n` bits within a chunk are all set/cleared.
389	// This can cross bfield's
390	mi_decl_noinline static size_t mi_bchunk_popcountNC(mi_bchunk_t* chunk, size_t field_idx, size_t idx, size_t n) {
391	  mi_assert_internal((field_idx*MI_BFIELD_BITS) + idx + n <= MI_BCHUNK_BITS);
392	  size_t count = 0;
393	  while (n > 0) {
394	    size_t m = MI_BFIELD_BITS - idx;   // m is the bits to xset in this field
395	    if (m > n) { m = n; }
396	    mi_assert_internal(idx + m <= MI_BFIELD_BITS);
397	    mi_assert_internal(field_idx < MI_BCHUNK_FIELDS);
398	    const size_t mask = mi_bfield_mask(m, idx);
399	    count += mi_bfield_atomic_popcount_mask(&chunk->bfields[field_idx], mask);
400	    // next field

