2197	// reserve huge pages evenly among the given number of numa nodes (or use the available ones as detected)
2198	int mi_reserve_huge_os_pages_interleave(size_t pages, size_t numa_nodes, size_t timeout_msecs) mi_attr_noexcept {
2199	  if (pages == 0) return 0;
2200	
2201	  // pages per numa node
2202	  int numa_count = (numa_nodes > 0 && numa_nodes <= INT_MAX ? (int)numa_nodes : _mi_os_numa_node_count());
2203	  if (numa_count <= 0) { numa_count = 1; }
2204	  const size_t pages_per = pages / numa_count;
2205	  const size_t pages_mod = pages % numa_count;
2206	  const size_t timeout_per = (timeout_msecs==0 ? 0 : (timeout_msecs / numa_count) + 50);
2207	
2208	  // reserve evenly among numa nodes
2209	  for (int numa_node = 0; numa_node < numa_count && pages > 0; numa_node++) {
2210	    size_t node_pages = pages_per;  // can be 0
2211	    if ((size_t)numa_node < pages_mod) { node_pages++; }
2212	    int err = mi_reserve_huge_os_pages_at(node_pages, numa_node, timeout_per);
2213	    if (err) return err;
2214	    if (pages < node_pages) {
2215	      pages = 0;
2216	    }
2217	    else {
2218	      pages -= node_pages;
2219	    }
2220	  }
2221	
2222	  return 0;
2223	}
