2241	
2242	static long mi_arena_purge_delay(void) {
2243	  // <0 = no purging allowed, 0=immediate purging, >0=milli-second delay
2244	  const long delay = mi_option_get(mi_option_purge_delay);
2245	  const long mult  = mi_option_get(mi_option_arena_purge_mult);
2246	  if (delay<0 || mult<0)   { return -1; }
2247	  if (delay==0 || mult==0) { return 0; }
2248	  size_t total;
2249	  if (mi_mul_overflow((size_t)delay, (size_t)mult, &total)) { return delay; }
2250	  if (total > LONG_MAX) { return delay; }
2251	  return (long)total;
2252	}
2253	
2254	// reset or decommit in an arena and update the commit bitmap
2255	// assumes we own the area (i.e. slices_free is claimed by us)
2256	// returns if the memory is no longer committed (versus reset which keeps the commit)
2257	static bool mi_arena_purge(mi_arena_t* arena, size_t slice_index, size_t slice_count) {
2258	  mi_assert_internal(!arena->memid.is_pinned);
2259	  mi_assert_internal(mi_bbitmap_is_clearN(arena->slices_free, slice_index, slice_count));
2260	
2261	  const size_t size = mi_size_of_slices(slice_count);
2262	  void* const p = mi_arena_slice_start(arena, slice_index);
2263	  //const bool all_committed = mi_bitmap_is_setN(arena->slices_committed, slice_index, slice_count);
2264	  size_t already_committed;
2265	  mi_bitmap_setN(arena->slices_committed, slice_index, slice_count, &already_committed); // pretend all committed.. (as we lack a clearN call that counts the already set bits..)
2266	  const bool all_committed = (already_committed == slice_count);
2267	  const bool needs_recommit = _mi_os_purge_ex(arena->subproc, p, size, all_committed /* allow reset? */, mi_size_of_slices(already_committed), arena->commit_fun, arena->commit_fun_arg);
2268	
2269	  if (needs_recommit) {
2270	    // no longer committed
2271	    mi_bitmap_clearN(arena->slices_committed, slice_index, slice_count);
2272	    // we just counted in the purge to decommit all, but the some part was not committed so adjust that here
2273	    // mi_subproc_stat_decrease(arena->subproc, committed, mi_size_of_slices(slice_count - already_committed));
2274	  }
2275	  else if (!all_committed) {
2276	    // we cannot assume any of these are committed any longer (even with reset since we did setN and may have marked uncommitted slices as committed)
2277	    mi_bitmap_clearN(arena->slices_committed, slice_index, slice_count);
2278	    // we adjust the commit count as parts will be re-committed
2279	    // mi_subproc_stat_decrease(arena->subproc, committed, mi_size_of_slices(already_committed));
2280	  }
2281	
2282	  return needs_recommit;
2283	}
