2285	
2286	// Schedule a purge. This is usually delayed to avoid repeated decommit/commit calls.
2287	// Note: assumes we (still) own the area as we may purge immediately
2288	static void mi_arena_schedule_purge(mi_arena_t* arena, size_t slice_index, size_t slice_count) {
2289	  const long delay = mi_arena_purge_delay();
2290	  if (arena->memid.is_pinned || delay < 0 || _mi_preloading()) return;  // is purging allowed at all?
2291	
2292	  mi_assert_internal(mi_bbitmap_is_clearN(arena->slices_free, slice_index, slice_count));
2293	  if (delay == 0) {
2294	    // purge directly
2295	    mi_arena_purge(arena, slice_index, slice_count);
2296	  }
2297	  else {
2298	    // schedule purge
2299	    const mi_msecs_t expire = _mi_clock_now() + delay;
2300	    mi_msecs_t expire0 = 0;
2301	    if (mi_atomic_casi64_strong_acq_rel(&arena->purge_expire, &expire0, expire)) {
2302	      // expiration was not yet set
2303	      // maybe set the global arenas expire as well (if it wasn't set already)
2304	      mi_assert_internal(expire0==0);
2305	      mi_atomic_casi64_strong_acq_rel(&arena->subproc->purge_expire, &expire0, expire);
2306	    }
2307	    else {
2308	      // already an expiration was set
2309	    }
2310	    mi_bitmap_setN(arena->slices_purge, slice_index, slice_count, NULL);
2311	  }
2312	}
2313	
2314	typedef struct mi_purge_visit_info_s {
2315	  mi_msecs_t now;
2316	  mi_msecs_t delay;
2317	  bool all_purged;
2318	  bool any_purged;
2319	} mi_purge_visit_info_t;
2320	
2321	static bool mi_arena_try_purge_range(mi_arena_t* arena, size_t slice_index, size_t slice_count) {
2322	  mi_assert(slice_count < MI_BCHUNK_BITS);
2323	  if (mi_bbitmap_try_clearNC(arena->slices_free, slice_index, slice_count)) {
2324	    // purge
2325	    bool decommitted = mi_arena_purge(arena, slice_index, slice_count); MI_UNUSED(decommitted);
2326	    mi_assert_internal(!decommitted || mi_bitmap_is_clearN(arena->slices_committed, slice_index, slice_count));
2327	    // and reset the free range
2328	    mi_bbitmap_setN(arena->slices_free, slice_index, slice_count);
2329	    return true;
2330	  }
2331	  else {
2332	    // was allocated again already
2333	    return false;
2334	  }
2335	}
2336	
2337	static bool mi_arena_try_purge_visitor(size_t slice_index, size_t slice_count, mi_arena_t* arena, void* arg) {
2338	  mi_purge_visit_info_t* vinfo = (mi_purge_visit_info_t*)arg;
2339	  // try to purge: first claim the free blocks
2340	  if (mi_arena_try_purge_range(arena, slice_index, slice_count)) {
2341	    vinfo->any_purged = true;
2342	    vinfo->all_purged = true;
2343	  }
2344	  else if (slice_count > 1)
2345	  {
2346	    // failed to claim the full range, try per slice instead
2347	    for (size_t i = 0; i < slice_count; i++) {
2348	      const bool purged = mi_arena_try_purge_range(arena, slice_index + i, 1);
2349	      vinfo->any_purged = vinfo->any_purged || purged;
2350	      vinfo->all_purged = vinfo->all_purged && purged;
2351	    }
2352	  }
2353	  // don't clear the purge bits as that is done atomically be the _bitmap_forall_set_ranges
2354	  // mi_bitmap_clearN(arena->slices_purge, slice_index, slice_count);
2355	  return true; // continue
2356	}
