2358	// returns
2359	// -1 = nothing was purged
2360	// 0  = nothing was purged yet because have not yet reached the expire time
2361	// 1  = some pages in the arena were purged
2362	static int mi_arena_try_purge(mi_arena_t* arena, mi_msecs_t now, bool force)
2363	{
2364	  // check pre-conditions
2365	  if (arena->memid.is_pinned) return -1;
2366	
2367	  // expired yet?
2368	  mi_msecs_t expire = mi_atomic_loadi64_relaxed(&arena->purge_expire);
2369	  if (expire==0) return -1;
2370	  if (!force && expire > now) return 0;
2371	
2372	  // reset expire
2373	  mi_atomic_storei64_release(&arena->purge_expire, (mi_msecs_t)0);
2374	  mi_subproc_stat_counter_increase(arena->subproc, arena_purges, 1);
2375	
2376	  // go through all purge info's  (with max MI_BFIELD_BITS ranges at a time)
2377	  // this also clears those ranges atomically (so any newly freed blocks will get purged next
2378	  // time around)
2379	  mi_purge_visit_info_t vinfo = { now, mi_arena_purge_delay(), true /*all?*/, false /*any?*/};
2380	
2381	  // we purge by at least `minslices` to not fragment transparent huge pages for example
2382	  const size_t minslices = mi_slice_count_of_size(_mi_os_minimal_purge_size());
2383	  _mi_bitmap_forall_setc_rangesn(arena->slices_purge, minslices, &mi_arena_try_purge_visitor, arena, &vinfo);
2384	
2385	  return (vinfo.any_purged ? 1 : -1);
2386	}
2387	
2388	
2389	static void mi_arenas_try_purge(bool force, bool visit_all, mi_subproc_t* subproc, size_t tseq)
2390	{
2391	  // try purge can be called often so try to only run when needed
2392	  const long delay = mi_arena_purge_delay();
2393	  if (_mi_preloading() || delay <= 0) return;  // nothing will be scheduled
2394	
2395	  // check if any arena needs purging?
2396	  const mi_msecs_t now = _mi_clock_now();
2397	  const mi_msecs_t arenas_expire = mi_atomic_loadi64_acquire(&subproc->purge_expire);
2398	  if (!visit_all && !force && (arenas_expire == 0 || arenas_expire > now)) return;
2399	
2400	  const size_t max_arena = mi_arenas_get_count(subproc);
2401	  if (max_arena == 0) return;
2402	
2403	  // allow only one thread to purge at a time (todo: allow concurrent purging?)
2404	  static mi_atomic_guard_t purge_guard;
2405	  mi_atomic_guard(&purge_guard)
2406	  {
2407	    // increase global expire: at most one purge per delay cycle
2408	    if (arenas_expire > now) { mi_atomic_storei64_release(&subproc->purge_expire, now + (delay/10)); }
2409	    const size_t arena_start = tseq % max_arena;
2410	    size_t max_purge_count = (visit_all ? max_arena : (max_arena/4)+1);
2411	    bool all_visited = true;
2412	    bool any_purged = false;
2413	    for (size_t _i = 0; _i < max_arena; _i++) {
2414	      size_t i = _i + arena_start;
2415	      if (i >= max_arena) { i -= max_arena; }
2416	      mi_arena_t* arena = mi_arena_from_index(subproc,i);
2417	      if (arena != NULL) {
2418	        const int purged = mi_arena_try_purge(arena, now, force);
2419	        if (purged >= 0) {      // purged, or arena expire is not yet reached
2420	          any_purged = true;
2421	          if (purged >= 1) {    // purged
2422	            if (max_purge_count <= 1) {
2423	              all_visited = false;
2424	              break;
2425	            }
2426	            max_purge_count--;
2427	          }
2428	        }
2429	      }
2430	    }
2431	    if (all_visited && !any_purged) {
2432	      mi_atomic_storei64_release(&subproc->purge_expire, (mi_msecs_t)0);
2433	    }
2434	  }
2435	}
