2449	static bool mi_heap_visit_page(mi_page_t* page, mi_heap_visit_info_t* vinfo) {
2450	  mi_heap_area_t area;
2451	  _mi_heap_area_init(&area, page);
2452	  mi_assert_internal(vinfo->heap == mi_page_heap(page));
2453	  if (!vinfo->visitor(vinfo->heap, &area, NULL, area.block_size, vinfo->arg)) {
2454	    return false;
2455	  }
2456	  if (vinfo->visit_blocks) {
2457	    return _mi_theap_area_visit_blocks(&area, page, vinfo->visitor, vinfo->arg);
2458	  }
2459	  else {
2460	    return true;
2461	  }
2462	}
2463	
2464	static bool mi_heap_visit_page_at(size_t slice_index, size_t slice_count, mi_arena_t* arena, void* arg) {
2465	  MI_UNUSED(slice_count);
2466	  mi_heap_visit_info_t* vinfo = (mi_heap_visit_info_t*)arg;
2467	  mi_page_t* page = mi_arena_page_at_slice(arena, slice_index);
2468	  return mi_heap_visit_page(page, vinfo);
