2470	
2471	bool _mi_heap_visit_blocks(mi_heap_t* heap, bool abandoned_only, bool visit_blocks, mi_block_visit_fun* visitor, void* arg) {
2472	  mi_assert(visitor!=NULL);
2473	  if (visitor==NULL) return false;
2474	  if (heap==NULL) { heap = mi_heap_main(); }
2475	  // visit all pages in a heap
2476	  // we don't have to claim because we assume we are the only thread running (with this heap).
2477	  // (but we could atomically claim as well by first doing abandoned_reclaim and afterwards reabandoning).
2478	  mi_heap_visit_info_t visit_info = { heap, visitor, arg, visit_blocks };
2479	  bool ok = true;
2480	  mi_forall_arenas(heap, NULL, 0, arena) {
