2546	
2547	  if (page->used==0) {
2548	    // free the page
2549	    _mi_arenas_page_free(page, theap);
2550	  }
2551	  else if (heap_target==NULL) {
2552	    #if MI_GUARDED
2553	    _mi_page_unguard_all(page);          // remove potential interior guard pages 
2554	    #endif
2555	    // destroy the page
2556	    page->used=0;                        // note: invariant `|local_free| + |free| == reserved - used`  does not hold in this case
2557	    _mi_arenas_page_free(page, theap);
2558	  }
2559	  else {
2560	    // move the page to `heap_target` as an abandoned page
2561	    // first remove it from the current heap
