2585	
2586	    // and then add it to the new target heap
2587	    if (arena != NULL) {
2588	      mi_arena_pages_t* arena_pages_target = mi_heap_ensure_arena_pages(heap_target, arena);
2589	      if mi_unlikely(arena_pages_target==NULL) {
