499	// Try to atomically clear a sequence of `n` bits within a chunk.
500	// Returns true if all bits transitioned from 1 to 0,
501	// and false otherwise leaving all bit fields as is.
502	// Note: this is the complex one as we need to unwind partial atomic operations if we fail halfway..
503	// `maybe_all_clear` is set to `true` if all the bfields involved become zero.
504	mi_decl_noinline static bool mi_bchunk_try_clearNC(mi_bchunk_t* chunk, size_t cidx, size_t n, bool* pmaybe_all_clear, bool* did_temp_clear_bits) {
505	  mi_assert_internal(cidx + n <= MI_BCHUNK_BITS);
506	  mi_assert_internal(n>0);
507	  if (pmaybe_all_clear != NULL) { *pmaybe_all_clear = true; }
508	  if (n==0) return true;
509	
510	  // first field
511	  const size_t start_idx = cidx % MI_BFIELD_BITS;
512	  const size_t start_field = cidx / MI_BFIELD_BITS;
513	  size_t field = start_field;
514	  size_t m = MI_BFIELD_BITS - start_idx;   // m are the bits to clear in this field
515	  if (m > n) { m = n; }
516	  mi_assert_internal(start_idx + m <= MI_BFIELD_BITS);
517	  mi_assert_internal(start_field < MI_BCHUNK_FIELDS);
518	  const mi_bfield_t mask_start = mi_bfield_mask(m, start_idx);
519	  bool maybe_all_clear;
520	  if (!mi_bfield_atomic_try_clear_mask(&chunk->bfields[field], mask_start, &maybe_all_clear, did_temp_clear_bits)) return false;
521	
522	  // done?
523	  mi_assert_internal(m <= n);
524	  n -= m;
525	
526	  // continue with mid fields and last field: if these fail we need to recover by unsetting previous fields
527	  // mid fields?
528	  while (n >= MI_BFIELD_BITS) {
529	    field++;
530	    mi_assert_internal(field < MI_BCHUNK_FIELDS);
531	    bool field_is_clear;
532	    if (!mi_bfield_atomic_try_clearX(&chunk->bfields[field], &field_is_clear)) goto restore;
533	    maybe_all_clear = maybe_all_clear && field_is_clear;
534	    n -= MI_BFIELD_BITS;
535	  }
536	
537	  // last field?
538	  if (n > 0) {
539	    mi_assert_internal(n < MI_BFIELD_BITS);
540	    field++;
541	    mi_assert_internal(field < MI_BCHUNK_FIELDS);
542	    const mi_bfield_t mask_end = mi_bfield_mask(n, 0);
543	    bool field_is_clear;
544	    if (!mi_bfield_atomic_try_clear_mask(&chunk->bfields[field], mask_end, &field_is_clear, did_temp_clear_bits)) goto restore;
545	    maybe_all_clear = maybe_all_clear && field_is_clear;
546	  }
547	
548	  if (pmaybe_all_clear != NULL) { *pmaybe_all_clear = maybe_all_clear; }
549	  return true;
550	
551	restore:
552	  // `field` is the index of the field that failed to set atomically; we need to restore all previous fields
553	  mi_assert_internal(field > start_field);
554	  if (did_temp_clear_bits != NULL) { *did_temp_clear_bits = true; }
555	  while( field > start_field) {
556	    field--;
557	    if (field == start_field) {
558	      mi_bfield_atomic_set_mask(&chunk->bfields[field], mask_start, NULL);
559	    }
560	    else {
561	      mi_bfield_atomic_setX(&chunk->bfields[field], NULL);  // mid-field: set all bits again
562	    }
563	  }
564	  return false;
565	}
