984	static bool mi_bchunk_bsr(mi_bchunk_t* chunk, size_t* pidx) {
985	  for (size_t i = MI_BCHUNK_FIELDS; i > 0; ) {
986	    i--;
987	    mi_bfield_t b = mi_atomic_load_relaxed(&chunk->bfields[i]);
988	    size_t idx;
989	    if (mi_bsr(b, &idx)) {
990	      *pidx = (i*MI_BFIELD_BITS) + idx;
991	      return true;
992	    }
993	  }
994	  return false;
995	}
