1297	/* --------------------------------------------------------------------------------
1298	  mi_bitmap_find
1299	  (used to find free pages)
1300	-------------------------------------------------------------------------------- */
1301	
1302	typedef bool (mi_bitmap_visit_fun_t)(mi_bitmap_t* bitmap, size_t chunk_idx, size_t n, size_t* idx, void* arg1, void* arg2);
1303	
1304	// Go through the bitmap and for every sequence of `n` set bits, call the visitor function.
1305	// If it returns `true` stop the search.
1306	static inline bool mi_bitmap_find(mi_bitmap_t* bitmap, size_t tseq, size_t n, size_t* pidx, mi_bitmap_visit_fun_t* on_find, void* arg1, void* arg2)
1307	{
1308	  const size_t chunkmap_max = _mi_divide_up(mi_bitmap_chunk_count(bitmap), MI_BFIELD_BITS);
1309	  for (size_t i = 0; i < chunkmap_max; i++) {
1310	    // and for each chunkmap entry we iterate over its bits to find the chunks
1311	    const mi_bfield_t cmap_entry = mi_atomic_load_relaxed(&bitmap->chunkmap.bfields[i]);
1312	    size_t hi;
1313	    if (mi_bfield_find_highest_bit(cmap_entry, &hi)) {
1314	      size_t eidx = 0;
1315	      mi_bfield_cycle_iterate(cmap_entry, tseq%8, hi+1, eidx, Y) // reduce the tseq to 8 bins to reduce using extra memory (see `mstress`)
1316	      {
1317	        mi_assert_internal(eidx <= MI_BFIELD_BITS);
1318	        const size_t chunk_idx = i*MI_BFIELD_BITS + eidx;
1319	        mi_assert_internal(chunk_idx < mi_bitmap_chunk_count(bitmap));
1320	        if ((*on_find)(bitmap, chunk_idx, n, pidx, arg1, arg2)) {
1321	          return true;
1322	        }
1323	      }
1324	      mi_bfield_cycle_iterate_end(Y);
1325	    }
1326	  }
1327	  return false;
1328	}
