1331	/* --------------------------------------------------------------------------------
1332	  Bitmap: try_find_and_claim  -- used to allocate abandoned pages
1333	  note: the compiler will fully inline the indirect function call
1334	-------------------------------------------------------------------------------- */
1335	
1336	typedef struct mi_claim_fun_data_s {
1337	  mi_arena_t*   arena;  
1338	} mi_claim_fun_data_t;
1339	
1340	static bool mi_bitmap_try_find_and_claim_visit(mi_bitmap_t* bitmap, size_t chunk_idx, size_t n, size_t* pidx, void* arg1, void* arg2)
1341	{
1342	  mi_assert_internal(n==1); MI_UNUSED(n);
1343	  mi_claim_fun_t* claim_fun = (mi_claim_fun_t*)arg1;
1344	  mi_claim_fun_data_t* claim_data = (mi_claim_fun_data_t*)arg2;
1345	  size_t cidx;
1346	  if mi_likely(mi_bchunk_try_find_and_clear(&bitmap->chunks[chunk_idx], &cidx)) {
1347	    const size_t slice_index = (chunk_idx * MI_BCHUNK_BITS) + cidx;
1348	    mi_assert_internal(slice_index < mi_bitmap_max_bits(bitmap));
1349	    bool keep_set = true;
1350	    if ((*claim_fun)(slice_index, claim_data->arena, &keep_set)) {
1351	      // success!
1352	      mi_assert_internal(!keep_set);
1353	      *pidx = slice_index;
1354	      return true;
1355	    }
1356	    else {
1357	      // failed to claim it, set abandoned mapping again (unless the page was freed and keep_set will be false)
1358	      if (keep_set) {
1359	        const bool wasclear = mi_bchunk_set(&bitmap->chunks[chunk_idx], cidx, NULL);
1360	        mi_bitmap_chunkmap_set(bitmap, chunk_idx);
1361	        mi_assert_internal(wasclear); MI_UNUSED(wasclear);
1362	      }
1363	    }
1364	  }
1365	  else {
1366	    // we may find that all are cleared only on a second iteration but that is ok as
1367	    // the chunkmap is a conservative approximation.
1368	    mi_bitmap_chunkmap_try_clear(bitmap, chunk_idx);
1369	  }
1370	  return false;
1371	}
1372	
1373	// Find a set bit in the bitmap and try to atomically clear it and claim it.
1374	// (Used to find pages in the pages_abandoned bitmaps.)
1375	mi_decl_nodiscard bool mi_bitmap_try_find_and_claim(mi_bitmap_t* bitmap, size_t tseq, size_t* pidx,
1376	  mi_claim_fun_t* claim, mi_arena_t* arena )
1377	{
1378	  mi_claim_fun_data_t claim_data = { arena };
1379	  return mi_bitmap_find(bitmap, tseq, 1, pidx, &mi_bitmap_try_find_and_claim_visit, (void*)claim, &claim_data);
1380	}
