1383	bool mi_bitmap_bsr(mi_bitmap_t* bitmap, size_t* idx) {
1384	  const size_t chunkmap_max = _mi_divide_up(mi_bitmap_chunk_count(bitmap), MI_BFIELD_BITS);
1385	  for (size_t i = chunkmap_max; i > 0; ) {
1386	    i--;
1387	    mi_bfield_t cmap = mi_atomic_load_relaxed(&bitmap->chunkmap.bfields[i]);
1388	    size_t cmap_idx;
1389	    if (mi_bsr(cmap,&cmap_idx)) {
1390	      // from highest chunk to lowest (scan all in case the cmap entry was stale)
1391	      for (size_t j = cmap_idx+1; j>0; ) {
1392	        j--;
1393	        const size_t chunk_idx = (i*MI_BFIELD_BITS) + j;
1394	        size_t cidx;
1395	        if (mi_bchunk_bsr(&bitmap->chunks[chunk_idx], &cidx)) {
1396	          *idx = (chunk_idx * MI_BCHUNK_BITS) + cidx;
1397	          return true;
1398	        }
1399	      }
1400	    }
1401	  }
1402	  return false;
1403	}
