1596	// initialize a bitmap to all unset; avoid a mem_zero if `already_zero` is true
1597	// returns the size of the bitmap
1598	size_t mi_bbitmap_init(mi_subproc_t* subproc, mi_bbitmap_t* bbitmap, size_t bit_count, bool already_zero) {
1599	  size_t chunk_count;
1600	  const size_t size = mi_bbitmap_size(bit_count, &chunk_count);
1601	  if (!already_zero) {
1602	    _mi_memzero_aligned(bbitmap, size);
1603	  }
1604	  mi_atomic_store_release(&bbitmap->chunk_count, chunk_count);
1605	  mi_assert_internal(mi_atomic_load_relaxed(&bbitmap->chunk_count) <= MI_BITMAP_MAX_CHUNK_COUNT);
1606	  bbitmap->subproc = subproc;
1607	  return size;
1608	}
