1807	  const size_t cmap_acc_bits   = 1 + (chunk_acc % MI_BFIELD_BITS);
1808	
1809	  // create a mask over the chunkmap entries to iterate over them efficiently
1810	  mi_assert_internal(MI_BFIELD_BITS >= MI_BCHUNK_FIELDS);
1811	  const mi_bfield_t cmap_mask  = mi_bfield_mask(cmap_max_count,0);
1812	  const size_t cmap_cycle      = cmap_acc+1;
1813	  const mi_chunkbin_t bbin = mi_chunkbin_of(n);
1814	  // visit each cmap entry
1815	  size_t cmap_idx = 0;
1816	  mi_bfield_cycle_iterate(cmap_mask, tseq, cmap_cycle, cmap_idx, X)
1817	  {
