1836	    // iterations through all entries.
1837	    mi_assert_internal(bbin < MI_CBIN_NONE);
1838	    for (mi_chunkbin_t ibin = MI_CBIN_SMALL; ibin <= MI_CBIN_NONE;
1839	          // skip from bbin to NONE (so, say, a SMALL will never be placed in a OTHER, MEDIUM, or LARGE chunk to reduce fragmentation)
1840	          ibin = (ibin == bbin ? MI_CBIN_NONE : mi_chunkbin_inc(ibin)))
1841	    {
1842	      mi_assert_internal(ibin < MI_CBIN_COUNT);
1843	      const mi_bfield_t cmap_bin = cmap_bins[ibin];
1844	      size_t eidx = 0;
1845	      mi_bfield_cycle_iterate(cmap_bin, tseq, cmap_entry_cycle, eidx, Y)
1846	      {
1847	        // assertion doesn't quite hold as the max_accessed may be out-of-date
1848	        // mi_assert_internal(cmap_entry_cycle > eidx || ibin == MI_CBIN_NONE);
1849	
1850	        // get the chunk
1851	        const size_t chunk_idx = cmap_idx*MI_BFIELD_BITS + eidx;
1852	        mi_bchunk_t* chunk = &bbitmap->chunks[chunk_idx];
1853	
1854	        size_t cidx;
1855	        bool did_temp_clear_bits = false;
1856	        if ((*on_find)(chunk, n, &cidx, &did_temp_clear_bits)) {
1857	          if (cidx==0 && ibin == MI_CBIN_NONE) { // only the first block determines the size bin
1858	            // this chunk is now reserved for the `bbin` size class
1859	            mi_bbitmap_set_chunk_bin(bbitmap, chunk_idx, bbin);
1860	          }
1861	          *pidx = (chunk_idx * MI_BCHUNK_BITS) + cidx;
